CREATE TABLE IF NOT EXISTS pedidos (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL, sede_id UUID NOT NULL, mesa_id UUID NOT NULL, estado TEXT DEFAULT 'ABIERTO', total NUMERIC(12,2) DEFAULT 0, client_session_id TEXT, idempotency_key TEXT UNIQUE, UNIQUE(id, tenant_id));
CREATE TABLE IF NOT EXISTS comandas (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id UUID NOT NULL, pedido_id UUID NOT NULL, producto_id UUID NOT NULL, cantidad INT CHECK (cantidad>0), precio_unitario NUMERIC(12,2) NOT NULL, estado TEXT DEFAULT 'PENDIENTE', UNIQUE(id, tenant_id), FOREIGN KEY (pedido_id, tenant_id) REFERENCES pedidos(id, tenant_id));
